    n := v::numeric;
    IF p IS NOT NULL AND (n <> round(n,s) OR abs(n) >= power(10::numeric,p-s)) THEN
        RAISE EXCEPTION 'Numeric cannot fit NUMBER(%,%) without rounding', p, s;
    END IF;
