    IF EXISTS((SELECT ma_dbhc COLLATE "C", ma_cha COLLATE "C", ten COLLATE "C", tinh_trang COLLATE "C", status COLLATE "C", created_date, id, ma_dbhc_sn COLLATE "C", is_lt, is_cap_xa, ngay_hieu_luc, ngay_het_hieu_luc FROM public.mirror_dm_dbhc EXCEPT ALL SELECT hdg_load.checked_text(ma_dbhc, 5, true) COLLATE "C", hdg_load.checked_text(ma_cha, 5, true) COLLATE "C", hdg_load.checked_text(ten, 200, true) COLLATE "C", hdg_load.checked_text(tinh_trang, 1, true) COLLATE "C", hdg_load.checked_text(status, 1, true) COLLATE "C", hdg_load.checked_timestamp(created_date, 0), hdg_load.checked_numeric(id, 20, 0), hdg_load.checked_text(ma_dbhc_sn, 200, true) COLLATE "C", hdg_load.checked_numeric(is_lt, 1, 0), hdg_load.checked_numeric(is_cap_xa, NULL, NULL), hdg_load.checked_timestamp(ngay_hieu_luc, 6), hdg_load.checked_timestamp(ngay_het_hieu_luc, 6) FROM hdg_stage.mirror_dm_dbhc WHERE load_run_id=p_run_id) UNION ALL (SELECT hdg_load.checked_text(ma_dbhc, 5, true) COLLATE "C", hdg_load.checked_text(ma_cha, 5, true) COLLATE "C", hdg_load.checked_text(ten, 200, true) COLLATE "C", hdg_load.checked_text(tinh_trang, 1, true) COLLATE "C", hdg_load.checked_text(status, 1, true) COLLATE "C", hdg_load.checked_timestamp(created_date, 0), hdg_load.checked_numeric(id, 20, 0), hdg_load.checked_text(ma_dbhc_sn, 200, true) COLLATE "C", hdg_load.checked_numeric(is_lt, 1, 0), hdg_load.checked_numeric(is_cap_xa, NULL, NULL), hdg_load.checked_timestamp(ngay_hieu_luc, 6), hdg_load.checked_timestamp(ngay_het_hieu_luc, 6) FROM hdg_stage.mirror_dm_dbhc WHERE load_run_id=p_run_id EXCEPT ALL SELECT ma_dbhc COLLATE "C", ma_cha COLLATE "C", ten COLLATE "C", tinh_trang COLLATE "C", status COLLATE "C", created_date, id, ma_dbhc_sn COLLATE "C", is_lt, is_cap_xa, ngay_hieu_luc, ngay_het_hieu_luc FROM public.mirror_dm_dbhc)) THEN RAISE EXCEPTION 'Mirror content differs for mirror_dm_dbhc; publish refused'; END IF;

    UPDATE hdg_load.control SET bootstrap_published=true,
      last_run_id=CASE WHEN copied THEN p_run_id ELSE last_run_id END WHERE id=1;
    UPDATE hdg_load.runs SET status=CASE WHEN copied THEN 'COMMITTED' ELSE 'NOOP' END,
      finished_at=clock_timestamp() WHERE run_id=p_run_id;
    RETURN CASE WHEN copied THEN 'COMMITTED' ELSE 'NOOP' END;
END $publish$;
COMMIT;
